function db(){static $pdo;global $config;if(!$pdo){if(!is_dir(__DIR__.'/data'))mkdir(__DIR__.'/data',0755,true);$pdo=new PDO('sqlite:'.$config['storage']);$pdo->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$pdo->exec('PRAGMA foreign_keys=ON');$pdo->exec('CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,user_id TEXT UNIQUE,password_hash TEXT,totp_secret TEXT,wallet_address TEXT,balance_sat INTEGER DEFAULT 0,active INTEGER DEFAULT 0,created_at TEXT)');$pdo->exec('CREATE TABLE IF NOT EXISTS transactions(id INTEGER PRIMARY KEY,type TEXT,status TEXT,from_user TEXT,to_user TEXT,amount_sat INTEGER DEFAULT 0,fee_sat INTEGER DEFAULT 0,txid TEXT,details TEXT,created_at TEXT)');$pdo->exec('CREATE TABLE IF NOT EXISTS attempts(id INTEGER PRIMARY KEY,ip TEXT,created_at INTEGER)');}return $pdo;}
function e($s){return htmlspecialchars((string)$s,ENT_QUOTES,'UTF-8');}function now(){return gmdate('c');}function post($k,$d=''){return trim((string)($_POST[$k]??$d));}function csrf(){if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(32));return $_SESSION['csrf'];}function checkcsrf(){if($_SERVER['REQUEST_METHOD']==='POST'&&!hash_equals($_SESSION['csrf']??'',$_POST['csrf']??'')){http_response_code(400);exit('Invalid CSRF token.');}}function token(){echo '<input type="hidden" name="csrf" value="'.e(csrf()).'">';}
function sat_to_btc($s){return number_format(((int)$s)/100000000,8,'.','');}function btc_to_sat($b){return (int)round(((float)$b)*100000000);}function usd_to_sat($usd){global $config;return (int)round(((float)$usd/$config['btc_usd_rate'])*100000000);}function sat_to_usd($sat){global $config;return (((int)$sat)/100000000)*$config['btc_usd_rate'];}function usd($n){return number_format((float)$n,2,'.',',');}
function btcaddr($v){return preg_match('/^(bc1|tb1|bcrt1|[13mn2])[a-zA-HJ-NP-Z0-9]{25,90}$/',$v);}function txidok($v){return $v===''||preg_match('/^[a-fA-F0-9]{64}$/',$v);}function uid(){return 'DM-'.strtoupper(bin2hex(random_bytes(4)));}function current_user(){if(empty($_SESSION['uid']))return null;$s=db()->prepare('SELECT * FROM users WHERE user_id=?');$s->execute([$_SESSION['uid']]);return $s->fetch(PDO::FETCH_ASSOC)?:null;}function need_user(){if(!current_user()){header('Location:?p=login');exit;}}function need_admin(){if(empty($_SESSION['admin'])){header('Location:?p=admin');exit;}}
function total_sat(){return (int)db()->query('SELECT COALESCE(SUM(balance_sat),0) FROM users WHERE active=1')->fetchColumn();}function share($sat){$t=total_sat();return $t>0?($sat/$t*100):0;}function tx($type,$status,$from,$to,$amt,$fee,$txid,$details){$s=db()->prepare('INSERT INTO transactions(type,status,from_user,to_user,amount_sat,fee_sat,txid,details,created_at) VALUES(?,?,?,?,?,?,?,?,?)');$s->execute([$type,$status,$from,$to,$amt,$fee,$txid,$details,now()]);}
function b32e($d){$a='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';$bits='';$o='';for($i=0;$i<strlen($d);$i++)$bits.=str_pad(decbin(ord($d[$i])),8,'0',STR_PAD_LEFT);foreach(str_split($bits,5) as $c){if(strlen($c)<5)$c=str_pad($c,5,'0');$o.=$a[bindec($c)];}return $o;}function b32d($b){$a='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';$b=strtoupper(preg_replace('/[^A-Z2-7]/','',$b));$bits='';$o='';for($i=0;$i<strlen($b);$i++){ $v=strpos($a,$b[$i]); if($v!==false)$bits.=str_pad(decbin($v),5,'0',STR_PAD_LEFT);}foreach(str_split($bits,8) as $c)if(strlen($c)===8)$o.=chr(bindec($c));return $o;}function secret(){return b32e(random_bytes(20));}function code($sec,$time=null){$time=$time??time();$ctr=floor($time/30);$hash=hash_hmac('sha1',pack('N*',0).pack('N*',$ctr),b32d($sec),true);$off=ord(substr($hash,-1))&15;$v=((ord($hash[$off])&127)<<24)|(ord($hash[$off+1])<<16)|(ord($hash[$off+2])<<8)|ord($hash[$off+3]);return str_pad($v%1000000,6,'0',STR_PAD_LEFT);}function okcode($sec,$c){$c=preg_replace('/\D/','',$c);for($i=-1;$i<=1;$i++)if(hash_equals(code($sec,time()+$i*30),$c))return true;return false;}
function canlogin(){ $ip=$_SERVER['REMOTE_ADDR']??'x';db()->prepare('DELETE FROM attempts WHERE created_at<?')->execute([time()-900]);$s=db()->prepare('SELECT COUNT(*) FROM attempts WHERE ip=?');$s->execute([$ip]);return (int)$s->fetchColumn()<8;}function fail(){db()->prepare('INSERT INTO attempts(ip,created_at) VALUES(?,?)')->execute([$_SERVER['REMOTE_ADDR']??'x',time()]);}
