 if($p==='activation_request'){need_user();$u=current_user();$net=usd_to_sat($config['activation_value_usd']);$fee=usd_to_sat($config['exchange_fee_usd']);$id=post('txid');if(!txidok($id))$err='Enter a valid 64-character BTC transaction ID or leave it empty.';else{tx('activation','pending',$u['user_id'],null,$net,$fee,$id,'Activation review. Expected total BTC: '.sat_to_btc($net+$fee));$msg='Activation request submitted.';}}
 if($p==='deposit'){need_user();$u=current_user();$sat=btc_to_sat(post('btc'));$fee=usd_to_sat($config['exchange_fee_usd']);$id=post('txid');if($sat<=$fee)$err='Deposit must be greater than the 1 USD BTC fee.';elseif(!txidok($id))$err='Enter a valid 64-character BTC transaction ID or leave it empty.';else{tx('deposit','pending',$u['user_id'],null,$sat-$fee,$fee,$id,'BTC deposit review. Gross BTC: '.sat_to_btc($sat));$msg='Deposit request submitted.';}}
 if($p==='withdraw'){need_user();$u=current_user();$gross=btc_to_sat(post('btc'));$fee=usd_to_sat($config['exchange_fee_usd']);if($gross<=$fee||$gross>$u['balance_sat'])$err='Invalid amount. It must include the fee and not exceed your balance.';else{tx('withdrawal','pending',$u['user_id'],null,$gross-$fee,$fee,'','Payout wallet: '.$u['wallet_address']);$msg='Withdrawal request submitted.';}}
 if($p==='transfer'){need_user();$u=current_user();$sat=btc_to_sat(post('btc'));$to=post('to_user');$s=db()->prepare('SELECT * FROM users WHERE user_id=? AND active=1');$s->execute([$to]);$r=$s->fetch(PDO::FETCH_ASSOC);if(!$r)$err='Target User ID not found or inactive.';elseif($to===$u['user_id'])$err='You cannot transfer to yourself.';elseif($sat<=0||$sat>$u['balance_sat'])$err='Invalid transfer amount.';else{$d=db();$d->beginTransaction();$d->prepare('UPDATE users SET balance_sat=balance_sat-? WHERE user_id=?')->execute([$sat,$u['user_id']]);$d->prepare('UPDATE users SET balance_sat=balance_sat+? WHERE user_id=?')->execute([$sat,$to]);tx('transfer','completed',$u['user_id'],$to,$sat,0,'','Internal BTC-value transfer.');$d->commit();$msg='Transfer completed.';}}
 if($p==='settings'){need_user();if(!btcaddr(post('wallet')))$err='Enter a valid Bitcoin wallet address.';else{db()->prepare('UPDATE users SET wallet_address=? WHERE user_id=?')->execute([post('wallet'),current_user()['user_id']]);$msg='Wallet updated.';}}
 if($p==='admin_action'){need_admin();$id=(int)post('txid');$act=post('action');$s=db()->prepare('SELECT * FROM transactions WHERE id=?');$s->execute([$id]);$t=$s->fetch(PDO::FETCH_ASSOC);if($t&&$t['status']==='pending'){$d=db();$d->beginTransaction();if($act==='approve'){if($t['type']==='activation')$d->prepare('UPDATE users SET active=1,balance_sat=balance_sat+? WHERE user_id=?')->execute([$t['amount_sat'],$t['from_user']]);elseif($t['type']==='deposit')$d->prepare('UPDATE users SET balance_sat=balance_sat+? WHERE user_id=?')->execute([$t['amount_sat'],$t['from_user']]);elseif($t['type']==='withdrawal')$d->prepare('UPDATE users SET balance_sat=balance_sat-? WHERE user_id=? AND balance_sat>=?')->execute([$t['amount_sat']+$t['fee_sat'],$t['from_user'],$t['amount_sat']+$t['fee_sat']]);$d->prepare('UPDATE transactions SET status="approved" WHERE id=?')->execute([$id]);}else{$d->prepare('UPDATE transactions SET status="rejected" WHERE id=?')->execute([$id]);}$d->commit();}header('Location:?p=admin_dashboard');exit;}
