elseif($p==='settings'){need_user();$u=current_user();echo '<div class="card"><h2>Settings</h2><form method="post">';token();echo '<div class="field"><label>Bitcoin wallet address</label><input name="wallet" value="'.e($u['wallet_address']).'" required></div><button class="btn">Save</button></form></div>';}
elseif($p==='admin'){echo '<div class="card"><h2>Admin login</h2><form method="post">';token();echo '<div class="field"><label>Admin user</label><input name="admin_user" value="admin" required></div><div class="field"><label>Password</label><input type="password" name="password" required></div><button class="btn">Login</button></form></div>';}
elseif($p==='admin_dashboard'){need_admin();$users=db()->query('SELECT * FROM users ORDER BY id DESC')->fetchAll(PDO::FETCH_ASSOC);$txs=db()->query('SELECT * FROM transactions ORDER BY id DESC LIMIT 120')->fetchAll(PDO::FETCH_ASSOC);echo '<div class="tabs"><a class="btn secondary" href="?p=admin_logout">Admin logout</a></div><div class="grid"><div class="card"><h3>Total Dark-Money BTC value</h3><p>'.sat_to_btc(total_sat()).' BTC</p><p class="muted">$'.usd(sat_to_usd(total_sat())).'</p></div><div class="card"><h3>Users</h3><p>'.count($users).'</p></div></div><div class="card"><h2>Users</h2><table><tr><th>User</th><th>Active</th><th>BTC</th><th>Share</th><th>Wallet</th></tr>';foreach($users as $u)echo '<tr><td><code>'.e($u['user_id']).'</code></td><td>'.($u['active']?'yes':'no').'</td><td>'.sat_to_btc($u['balance_sat']).'</td><td>'.usd(share($u['balance_sat'])).'%</td><td><code>'.e($u['wallet_address']).'</code></td></tr>';echo '</table></div><div class="card"><h2>BTC review queue</h2><table><tr><th>ID</th><th>Type</th><th>Status</th><th>User</th><th>Amount BTC</th><th>Fee BTC</th><th>TXID</th><th>Action</th></tr>';foreach($txs as $t){echo '<tr><td>'.e($t['id']).'</td><td>'.e($t['type']).'</td><td>'.e($t['status']).'</td><td>'.e($t['from_user']).'</td><td>'.sat_to_btc($t['amount_sat']).'</td><td>'.sat_to_btc($t['fee_sat']).'</td><td><code>'.e($t['txid']).'</code></td><td>';if($t['status']==='pending'){echo '<form method="post" action="?p=admin_action">';token();echo '<input type="hidden" name="txid" value="'.e($t['id']).'"><button class="btn" name="action" value="approve">Approve</button> <button class="btn secondary" name="action" value="reject">Reject</button></form>';}echo '</td></tr>';}echo '</table></div>';}
else echo '<div class="card"><h2>Page not found</h2></div>';footx();
PHP;
    w(__DIR__.'/config.php',$cfg);w(__DIR__.'/free.txt',$free);w(__DIR__.'/.htaccess',$ht);w(__DIR__.'/data/.htaccess','Require all denied' . PHP_EOL);w(__DIR__.'/assets/style.css',$css);w(__DIR__.'/index.php',$index);w(__DIR__.'/data/setup.lock','Installed '.gmdate('c').PHP_EOL);$done=true;
