?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Secure Money Transfer Setup</title><style>body{margin:0;background:#070911;color:#f4f7fb;font-family:system-ui,-apple-system,Segoe UI,Arial}.wrap{max-width:880px;margin:auto;padding:32px}.card{background:#111827;border:1px solid #263247;border-radius:22px;padding:24px;box-shadow:0 18px 60px #0008}.field{display:flex;flex-direction:column;gap:7px;margin:14px 0}input{background:#070911;color:#fff;border:1px solid #263247;border-radius:13px;padding:13px}.btn{background:linear-gradient(135deg,#7c4dff,#4f46e5);border:0;color:white;border-radius:13px;padding:12px 16px;font-weight:800}.bad{color:#ff5c7a}.good{color:#34d399}.muted{color:#9ba8bd}code{background:#070911;border:1px solid #263247;padding:3px 6px;border-radius:8px}</style></head><body><div class="wrap"><div class="card"><h1>Secure Money Transfer BTC Setup</h1><?php if($done): ?><p class="good">Installation completed.</p><p>Created BTC-based Dark-Money website files.</p><p class="bad">Delete this setup file now.</p><p><a class="btn" href="index.php">Open website</a></p><?php else: ?><p class="muted">Creates the final BTC-based version with satoshi ledger, TOTP MFA, manual BTC review and no private-key storage.</p><?php if($errors): ?><ul class="bad"><?php foreach($errors as $er): ?><li><?=h($er)?></li><?php endforeach; ?></ul><?php endif; ?><form method="post"><div class="field"><label>Base URL</label><input name="base_url" value="<?=h((!empty($_SERVER['HTTPS'])?'https':'http').'://'.($_SERVER['HTTP_HOST']??'localhost').rtrim(dirname($_SERVER['SCRIPT_NAME']??''),'/'))?>" required></div><div class="field"><label>Fee Bitcoin address</label><input name="fee_address" required></div><div class="field"><label>Dark-Money Bitcoin address</label><input name="dark_address" required></div><div class="field"><label>BTC/USD rate for fee and activation calculation</label><input type="number" step="0.01" min="1" name="btc_usd_rate" required></div><div class="field"><label>Admin password</label><input type="password" minlength="12" name="admin_password" required></div><div class="field"><label>Repeat admin password</label><input type="password" minlength="12" name="admin_password2" required></div><button class="btn">Generate final BTC website</button></form><?php endif; ?></div></div></body></html>
